import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    index = int(ctx.index)
    inputs = torch.tensor([float(index % 3) + 0.2, float(index % 5) + 0.5, float(index % 7) + 0.9, float(index % 2) + 1.3])
    teacher_logits = torch.tensor([float(index % 3) + 0.1, float((index * 2) % 5) + 1.0, float((index * 3) % 7) + 2.0])
    return {"inputs": synth.Tensor(inputs), "teacher_probs": synth.Tensor(torch.softmax(teacher_logits, dim=0))}
dataset = synth.Spec("distillation-correlation", generator=samples, size=12, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class Student(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=3)
    def forward(self, inputs):
        return {"student_probs": torch.softmax(self.network(inputs), dim=-1)}
model = Student()
trainer = Trainer(model, train, recipe="structured-objective", recipe_config={"loss": "dist", "loss_kwargs": {"beta": 1.0, "gamma": 1.0}, "bindings": {"logits_or_prediction": {"output": "student_probs"}, "targets": {"batch": "teacher_probs"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
